import java.util.Arrays;

public class ByteVector {
    private byte[] data;
    private int length;

    public ByteVector() {
        this.data = new byte[32];
        this.length = 0;
    }

    public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteLength == 0) {
            return this;
        }

        int requiredLength = this.length + byteLength;
        if (requiredLength > data.length) {
            enlarge(requiredLength - data.length);
        }

        if (byteArrayValue == null) {
            Arrays.fill(data, this.length, this.length + byteLength, (byte) 0);
        } else {
            System.arraycopy(byteArrayValue, byteOffset, data, this.length, byteLength);
        }

        this.length = requiredLength;
        return this;
    }

    private void enlarge(final int size) {
        int newSize = Math.max(data.length << 1, data.length + size);
        data = Arrays.copyOf(data, newSize);
    }

    public static void main(String[] args) {
        ByteVector bv = new ByteVector();
        bv.putByteArray(new byte[]{1, 2, 3, 4}, 1, 2);
        System.out.println(Arrays.toString(bv.data));
    }
}

