import java.io.ByteArrayInputStream;
import java.io.DataInputStream;
import java.io.IOException;

final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    byte[] classFileBuffer = { /* This should be initialized with the actual class file bytes */ };
    try (DataInputStream dis = new DataInputStream(new ByteArrayInputStream(classFileBuffer))) {
        // Skip to the constant pool entry index
        dis.skipBytes(constantPoolEntryIndex);

        // Read the tag to ensure it's a CONSTANT_Utf8
        int tag = dis.readUnsignedByte();
        if (tag != 1) { // 1 represents CONSTANT_Utf8
            throw new IOException("Invalid constant pool entry type");
        }

        // Read the length of the UTF string
        int length = dis.readUnsignedShort();

        // Read the UTF string into the charBuffer
        for (int i = 0; i < length; i++) {
            charBuffer[i] = dis.readChar();
        }

        return new String(charBuffer, 0, length);
    } catch (IOException e) {
        e.printStackTrace();
        return null;
    }
