public class CompleteBipartiteGraphGenerator<V, E extends DefaultEdge> {

    @Override
    public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
        if (target == null || resultMap == null) {
            throw new IllegalArgumentException("Target graph and result map cannot be null");
        }

        // Assuming resultMap contains two keys "set1" and "set2" with lists of vertices
        @SuppressWarnings("unchecked")
        Iterable<V> set1 = (Iterable<V>) resultMap.get("set1");
        @SuppressWarnings("unchecked")
        Iterable<V> set2 = (Iterable<V>) resultMap.get("set2");

        if (set1 == null || set2 == null) {
            throw new IllegalArgumentException("Result map must contain 'set1' and 'set2' keys");
        }

        for (V vertex1 : set1) {
            target.addVertex(vertex1);
            for (V vertex2 : set2) {
                target.addVertex(vertex2);
                target.addEdge(vertex1, vertex2);
            }
        }
    }

    public static void main(String[] args) {
        Graph<String, DefaultEdge> graph = new SimpleGraph<>(DefaultEdge.class);
        Map<String, Iterable<String>> resultMap = Map.of(
            "set1", List.of("A", "B"),
            "set2", List.of("C", "D", "E")
        );

        CompleteBipartiteGraphGenerator<String, DefaultEdge> generator = new CompleteBipartiteGraphGenerator<>();
        generator.generateGraph(graph, resultMap);

        // Print the graph
        System.out.println("Vertices: " + graph.vertexSet());
        System.out.println("Edges: " + graph.edgeSet());
    }
}

