import java.util.Set;
import java.util.HashMap;
import java.util.Map;

public class Graph<V, E> {
    private Map<V, Map<V, Double>> edges;

    public Graph() {
        edges = new HashMap<>();
    }

    public void addEdge(V from, V to, double weight) {
        edges.computeIfAbsent(from, k -> new HashMap<>()).put(to, weight);
    }

    public double vertexWeight(V v) {
        double sum = 0.0;
        for (Map<V, Double> edgeMap : edges.values()) {
            if (edgeMap.containsKey(v)) {
                sum += edgeMap.get(v);
            }
        }
        return sum;
    }

    public static void main(String[] args) {
        Graph<String, Double> graph = new Graph<>();
        graph.addEdge("A", "B", 1.0);
        graph.addEdge("C", "B", 2.0);
        graph.addEdge("B", "D", 3.0);

        System.out.println(graph.vertexWeight("B")); // Output should be 3.0
    }
}

