import org.jgrapht.Graph;
import org.jgrapht.GraphPath;
import org.jgrapht.graph.GraphWalk;
import java.util.Set;
import java.util.List;
import java.util.ArrayList;
import java.util.Iterator;

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour.isEmpty()) {
        return new GraphWalk<>(graph, null, null, new ArrayList<>(), 0.0);
    }

    List<E> edgeList = new ArrayList<>(tour);
    List<V> vertexList = new ArrayList<>();

    Iterator<E> it = edgeList.iterator();
    E firstEdge = it.next();
    V startVertex = graph.getEdgeSource(firstEdge);
    V endVertex = graph.getEdgeTarget(firstEdge);

    vertexList.add(startVertex);
    vertexList.add(endVertex);

    while (it.hasNext()) {
        E edge = it.next();
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        if (source.equals(endVertex)) {
            vertexList.add(target);
            endVertex = target;
        } else if (target.equals(endVertex)) {
            vertexList.add(source);
            endVertex = source;
        } else if (source.equals(startVertex)) {
            vertexList.add(0, target);
            startVertex = target;
        } else if (target.equals(startVertex)) {
            vertexList.add(0, source);
            startVertex = source;
        } else {
            throw new IllegalArgumentException("The provided set of edges does not form a valid tour.");
        }
    }

    return new GraphWalk<>(graph, startVertex, endVertex, vertexList, edgeList, graph.getType().isWeighted() ? calculateTotalWeight(edgeList, graph) : 0.0);
}

private double calculateTotalWeight(List<E> edgeList, Graph<V,E> graph) {
    double totalWeight = 0.0;
    for (E edge : edgeList) {
        totalWeight += graph.getEdgeWeight(edge);
    }
    return totalWeight;
}

