public class TypeResolver {

    public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
        if (!(genericType instanceof ParameterizedType)) {
            return null;
        }

        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
        TypeVariable<?>[] typeVariables = targetType.getTypeParameters();

        if (actualTypeArguments.length != typeVariables.length) {
            return null;
        }

        Map<TypeVariable<?>, Type> typeVariableMap = new HashMap<>();
        for (int i = 0; i < typeVariables.length; i++) {
            typeVariableMap.put(typeVariables[i], actualTypeArguments[i]);
        }

        Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];
        for (int i = 0; i < actualTypeArguments.length; i++) {
            Type type = actualTypeArguments[i];
            if (type instanceof Class<?>) {
                resolvedArguments[i] = (Class<?>) type;
            } else if (type instanceof TypeVariable<?>) {
                TypeVariable<?> typeVariable = (TypeVariable<?>) type;
                Type resolvedType = typeVariableMap.get(typeVariable);
                if (resolvedType instanceof Class<?>) {
                    resolvedArguments[i] = (Class<?>) resolvedType;
                } else {
                    return null;
                }
            } else {
                return null;
            }
        }

        return resolvedArguments;
    }

    public static void main(String[] args) {
