import java.io.IOException;
import java.io.InputStream;

public class VarintReader {
    private InputStream input;

    public VarintReader(InputStream input) {
        this.input = input;
    }

    public long readRawVarint64() throws IOException {
        long result = 0;
        for (int shift = 0; shift < 64; shift += 7) {
            int b = input.read();
            if (b == -1) {
                throw new IOException("Unexpected end of input stream");
            }
            result |= (long) (b & 0x7F) << shift;
            if ((b & 0x80) == 0) {
                return result;
            }
        }
        throw new IOException("Malformed varint");
    }

    public static void main(String[] args) {
        // Example usage
        byte[] data = {0x96, 0x01}; // Example varint encoding for the number 150
        VarintReader reader = new VarintReader(new java.io.ByteArrayInputStream(data));
        try {
            System.out.println(reader.readRawVarint64()); // Should print 150
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

