    public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
        int totalSize = 0;
        while (node != null) {
            int size = node.size;
            out.write(node.buffer, node.start, size);
            totalSize += size;
            node = node.next;
        }
        return totalSize;
    }
}

class LinkedBuffer {
    byte[] buffer;
    int start;
    int size;
    LinkedBuffer next;
}

